let lang=localStorage.getItem('portfolio-language') || (navigator.language.startsWith('zh')?'zh':'en');
function notePath(id){const name=id==='3d'?'3d-reconstruction.md':id==='drone'?'drone-simulator.md':id==='fast'?'fast-ai-movie.md':'vehicle-identification.md';return `notes/${lang}/${name}`}
function render(){ const t=copy[lang]; document.documentElement.lang=lang==='zh'?'zh-CN':'en'; document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=t[node.dataset.i18n]); document.querySelector('.language-toggle').innerHTML=lang==='zh'?'<span>中</span><span>/</span><span>EN</span>':'<span>中</span><span>/</span><span>EN</span>'; document.querySelector('.language-toggle span:last-child').style.color=lang==='en'?'var(--mint)':''; document.querySelector('.language-toggle span:first-child').style.color=lang==='zh'?'var(--mint)':''; document.getElementById('projects').innerHTML=projects.map(p=>{const x=p[lang]; return `<article class="project"><div class="project-image"><img src="${p.image}" alt="${x.title}" loading="lazy"></div><div class="project-content"><span class="project-meta">${x.meta}</span><h3>${x.title}</h3><p>${x.desc}</p><div class="tags">${x.tags.map(tag=>`<span>${tag}</span>`).join('')}</div><div class="project-links"><a href="${notePath(p.id)}">${t.details}</a>${p.video?`<a href="${p.video}">${t.video}</a>`:''}</div></div></article>`}).join(''); localStorage.setItem('portfolio-language',lang); }
document.querySelector('.language-toggle').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';render();}); document.getElementById('year').textContent=new Date().getFullYear(); render();
